settings.custom_css:
selector .ak-badge { --width: auto; width: auto; }
selector .ak-card .elementor-widget-text-editor p { margin: 0; }
selector .ak-prev .elementor-button, selector .ak-next .elementor-button {
  width: 56px; height: 56px; padding: 0; display: flex; align-items: center; justify-content: center;
}
selector .ak-thumb { cursor: pointer; }
selector .ak-thumb img { filter: grayscale(1) brightness(.75); transition: filter .3s; }
selector .ak-thumb.is-on img, selector .ak-thumb:hover img { filter: none; }
@media (max-width: 1366px) {
  selector .ak-prev .elementor-button, selector .ak-next .elementor-button { width: 48px; height: 48px; }
}
